/* Acervo completo (com mods) e as facções, sob demanda. */
let _db = null;
export function carregarSoldados() {
  if (!_db) {
    _db = fetch(A3SOL_META.dbUrl)
      .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
      .catch((err) => { _db = null; throw err; });
  }
  return _db;
}
